const input = $input.all();
if (input.length !== 1) throw new Error('Нужна одна исходная точка.');
const {latitude, longitude, label} = input[0].json;
if (typeof latitude !== 'number' || !Number.isFinite(latitude) || latitude < -90 || latitude > 90 ||
    typeof longitude !== 'number' || !Number.isFinite(longitude) || longitude < -180 || longitude > 180) {
  throw new Error('Нужны числовые координаты из SQL или явного ввода пользователя.');
}
if (typeof label !== 'string' || !label.trim() || label.trim().length > 200 || /[\x00-\x1f]/.test(label)) {
  throw new Error('Нужно краткое название исходной точки до 200 символов.');
}
return [{json:{latitude, longitude, label:label.trim()}}];

const response = $input.first().json;
const body = response.body;
if (body && typeof body === 'object' && body.ok === false && body.error && typeof body.error.code === 'string') {
  return [{json:body}];
}
if (response.statusCode === 200 && body && body.ok === true && body.comparison?.complete === true &&
    Number.isFinite(body.distance_m) && Number.isFinite(body.duration_seconds) && body.destination?.id) {
  return [{json:body}];
}
return [{json:{ok:false,error:{code:'RoutingUnavailable',message:'Сервис расчёта до МКАД недоступен или вернул неполный ответ. Расстояние не определено.'}}}];
